CREATE OR REPLACE PROCEDURE public.sp_create_parent_communication(IN p_id uuid, IN p_tenant_id uuid, IN p_organization_id uuid, IN p_classroom_id uuid, IN p_child_id uuid, IN p_recipient_person_id uuid, IN p_recipient_user_id uuid, IN p_recipient_email character varying, IN p_recipient_name character varying, IN p_recipient_relationship character varying, IN p_communication_type character varying, IN p_reporting_date_start date, IN p_reporting_date_end date, IN p_title character varying, IN p_content_draft text, IN p_content_final text, IN p_family_conversation_starter text, IN p_evidence_summary_json jsonb, IN p_consent_verified boolean, IN p_consent_notes character varying, IN p_status character varying, IN p_teacher_id uuid, IN p_teacher_name character varying, IN p_approved_by_user_id uuid, IN p_approved_at timestamp with time zone, IN p_sent_at timestamp with time zone, IN p_delivery_channel character varying, IN p_delivery_status character varying, IN p_delivery_error text, IN p_idempotency_key character varying, IN p_created_at timestamp with time zone, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     -- Fallback: resolve organization_id if null or empty     IF p_organization_id IS NULL OR p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid THEN         IF p_classroom_id IS NOT NULL THEN             SELECT b.organization_id INTO p_organization_id             FROM classrooms c             JOIN branches b ON b.id = c.branch_id             WHERE c.id = p_classroom_id             LIMIT 1;         END IF;          IF p_organization_id IS NULL OR p_organization_id = '00000000-0000-0000-0000-000000000000'::uuid THEN             SELECT id INTO p_organization_id             FROM organizations             WHERE tenant_id = p_tenant_id             ORDER BY created_at ASC             LIMIT 1;         END IF;     END IF;      INSERT INTO parent_communications (         id, tenant_id, organization_id, classroom_id, child_id,         recipient_person_id, recipient_user_id, recipient_email, recipient_name, recipient_relationship,         communication_type, reporting_date_start, reporting_date_end,         title, content_draft, content_final, family_conversation_starter,         evidence_summary_json, consent_verified, consent_notes,         status, teacher_id, teacher_name, approved_by_user_id, approved_at, sent_at,         delivery_channel, delivery_status, delivery_error, idempotency_key,         created_at, updated_at     ) VALUES (         p_id, p_tenant_id, p_organization_id, p_classroom_id, p_child_id,         p_recipient_person_id, p_recipient_user_id, p_recipient_email, p_recipient_name, p_recipient_relationship,         p_communication_type, p_reporting_date_start, p_reporting_date_end,         p_title, p_content_draft, p_content_final, p_family_conversation_starter,         p_evidence_summary_json, p_consent_verified, p_consent_notes,         p_status, p_teacher_id, p_teacher_name, p_approved_by_user_id, p_approved_at, p_sent_at,         p_delivery_channel, p_delivery_status, p_delivery_error, p_idempotency_key,         p_created_at, p_updated_at     ); END; $procedure$ ;
